package com.yihe.framework.ehr;

import java.util.*;
import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.core.io.ClassPathResource;
import org.springframework.transaction.annotation.Transactional;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Organisation-scoped drafts and immutable releases. Editing never changes live matching. */
@Service
public class AutoReplyRules {
    final EhrRepository db;final EhrService ehr;
    public AutoReplyRules(EhrRepository db,EhrService ehr){this.db=db;this.ehr=ehr;}
    static final Map<String,String> CATEGORIES=mapStrings("report","体检报告","abnormal","异常指标","review","复查预约","plan","健康方案","contact","联系管理员","miniapp","小程序使用","occupational","职业健康","health","健康知识");
    static Map<String,String> mapStrings(String...args){Map<String,String> m=new LinkedHashMap<>();for(int i=0;i<args.length;i+=2)m.put(args[i],args[i+1]);return m;}
    void staff(EhrActor a){require(!a.mobile,403,"规则配置仅供后台工作人员使用");}
    @SuppressWarnings("unchecked") Map<String,Object> seed(){try(InputStream in=new ClassPathResource("ehr/auto-reply-seed.json").getInputStream()){Map<String,Object> c=new ObjectMapper().readValue(in,Map.class);int n=0;for(Map<String,Object> r:(List<Map<String,Object>>)c.get("rules")){r.put("id",id());r.put("state","enabled");r.put("updatedAt",now());r.put("keywords",r.get("keywords"));r.put("match","any");n++;}return c;}catch(IOException e){throw new IllegalStateException("Default rule resource unavailable",e);}}
    Map<String,Object> config(EhrActor a,boolean lock){staff(a);return db.one("SELECT * FROM a_service_reply_configs WHERE scope_code=? AND data_mode=?"+(lock?" FOR UPDATE":""),a.scope,a.mode);}
    @Transactional public Map<String,Object> initialize(EhrActor a){staff(a);Map<String,Object> c=seed();db.exec("INSERT IGNORE INTO a_service_reply_configs(scope_code,data_mode,draft_json,draft_version,updated_at) VALUES(?,?,?,1,UTC_TIMESTAMP(6))",a.scope,a.mode,ehr.encode(c));return view(a);}
    @SuppressWarnings("unchecked") Map<String,Object> draft(Map<String,Object> row){return (Map<String,Object>)ehr.decode(row.get("draft_json"));}
    @SuppressWarnings("unchecked") List<Map<String,Object>> rules(Map<String,Object> c){return (List<Map<String,Object>>)c.get("rules");}
    @SuppressWarnings("unchecked") List<Map<String,Object>> knowledge(Map<String,Object> c){return (List<Map<String,Object>>)c.get("knowledge");}
    public Map<String,Object> view(EhrActor a){Map<String,Object> row=config(a,false);if(row==null)return map("initialized",false,"categories",CATEGORIES,"draft",null,"version",0,"release",null);Map<String,Object> released=row.get("active_release_id")==null?null:db.one("SELECT release_id id,release_number number,created_at time,actor_user actor,config_json FROM a_service_reply_releases WHERE release_id=? AND scope_code=? AND data_mode=?",row.get("active_release_id"),a.scope,a.mode);if(released!=null){Map<String,Object> live=draftRelease(released);released.remove("config_json");released.put("enabled",Boolean.TRUE.equals(live.get("enabled")));}return map("initialized",true,"categories",CATEGORIES,"draft",draft(row),"version",row.get("draft_version"),"release",released,"statistics",statistics(a));}
    @SuppressWarnings("unchecked") Map<String,Object> draftRelease(Map<String,Object> row){return (Map<String,Object>)ehr.decode(row.get("config_json"));}
    Map<String,Object> editing(EhrActor a,Map<String,Object> body){Map<String,Object> row=config(a,true);require(row!=null,409,"请先初始化默认规则");require(num(body.get("version"))==num(row.get("draft_version")),409,"草稿已被其他人修改，请刷新后重试");return row;}
    void save(EhrActor a,Map<String,Object> row,Map<String,Object> c){validate(c);db.exec("UPDATE a_service_reply_configs SET draft_json=?,draft_version=draft_version+1,updated_at=UTC_TIMESTAMP(6) WHERE scope_code=? AND data_mode=?",ehr.encode(c),a.scope,a.mode);}
    List<String> strings(Object raw,int max,int length,String label){require(raw instanceof List,422,label+"须为数组");List<String> out=new ArrayList<>();for(Object value:(List<?>)raw){require(value instanceof String,422,label+"格式不正确");String t=((String)value).trim();require(!t.isEmpty()&&t.length()<=length,422,label+"内容为空或过长");if(!out.contains(t))out.add(t);}require(out.size()<=max,422,label+"数量过多");return out;}
    void plain(String text,int max,String label){require(!text.trim().isEmpty()&&text.length()<=max,422,label+"不能为空且最多"+max+"字");require(!text.contains("<script")&&!text.contains("javascript:"),422,label+"不能包含脚本");}
    void variables(String text){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\{\\{([^}]+)}}").matcher(text);while(m.find())require(Arrays.asList("employee_name","employee_no","company_name").contains(m.group(1)),422,"不支持的变量："+m.group(1));require(text.replaceAll("\\{\\{(employee_name|employee_no|company_name)}}","").indexOf("{{")<0,422,"变量格式不正确");}
    @SuppressWarnings("unchecked") Map<String,Object> normalize(Map<String,Object> input){String title=text(input,"title"),type=text(input,"type"),category=text(input,"category"),boundary=text(input,"boundary"),reply=text(input,"reply"),state=text(input,"state"),match=text(input,"match");plain(title,100,"问题标题");plain(reply,1500,"回复内容");variables(reply);require(Arrays.asList("fixed","ai","handoff").contains(type),422,"回复类型无效");require(CATEGORIES.containsKey(category),422,"规则分类无效");require(Arrays.asList("general","doctor","human").contains(boundary),422,"回复边界无效");require(Arrays.asList("draft","enabled","disabled").contains(state),422,"规则状态无效");require(Arrays.asList("any","all","exact").contains(match),422,"匹配方式无效");List<String> keywords=strings(input.get("keywords"),20,60,"触发关键词");require(!keywords.isEmpty(),422,"至少需要一个关键词");for(String k:keywords)require(k.length()>=2,422,"关键词至少两个字符，避免误匹配");List<String> refs=strings(input.get("knowledgeIds"),10,40,"知识来源");if(type.equals("ai"))require(!refs.isEmpty(),422,"AI知识回复必须关联知识来源");int priority=num(input.get("priority"));require(priority>=0&&priority<=1000,422,"优先级为0至1000");return map("id",id(),"title",title,"type",type,"category",category,"boundary",boundary,"reply",reply,"state",state,"match",match,"keywords",keywords,"knowledgeIds",refs,"priority",priority,"updatedAt",now());}
    void validate(Map<String,Object> c){require(c.get("enabled") instanceof Boolean,422,"自动回复总开关无效");require(c.get("rules") instanceof List&&c.get("knowledge") instanceof List,422,"配置格式不正确");require(rules(c).size()<=300&&knowledge(c).size()<=30,422,"规则最多300条、知识来源最多30条");Set<String> ids=new HashSet<>(),knowledgeIds=new HashSet<>();for(Map<String,Object> k:knowledge(c)){String kid=text(k,"id");require(kid.matches("[A-Za-z0-9_-]{1,40}")&&knowledgeIds.add(kid),422,"知识来源编号无效或重复");plain(text(k,"title"),100,"知识标题");plain(text(k,"content"),6000,"知识正文");plain(text(k,"source"),300,"知识出处");require(k.get("enabled") instanceof Boolean,422,"知识状态无效");String url=text(k,"url");if(!url.isEmpty())try{java.net.URI u=java.net.URI.create(url);require("https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null,422,"出处链接须为HTTPS网页");}catch(IllegalArgumentException e){throw new EhrException(422,"出处链接格式错误");}}
        for(Map<String,Object> r:rules(c)){normalize(r);String rid=text(r,"id");CommunicationService.uuid(rid);require(ids.add(rid),422,"规则编号重复");for(String ref:strings(r.get("knowledgeIds"),10,40,"知识来源"))require(knowledgeIds.contains(ref),422,"知识来源不存在："+ref);}}
    @Transactional public Map<String,Object> upsert(EhrActor a,String rid,Map<String,Object> b){Map<String,Object> row=editing(a,b),c=draft(row);require(b.get("rule") instanceof Map,422,"请提供规则");Map<String,Object> item=normalize((Map<String,Object>)b.get("rule"));if(rid!=null){CommunicationService.uuid(rid);Map<String,Object> prior=rules(c).stream().filter(r->rid.equals(r.get("id"))).findFirst().orElse(null);require(prior!=null,404,"规则不存在");rules(c).remove(prior);item.put("id",rid);}rules(c).add(item);save(a,row,c);return view(a);}
    @Transactional public Map<String,Object> batch(EhrActor a,Map<String,Object> b){Map<String,Object> row=editing(a,b),c=draft(row);List<String> ids=strings(b.get("ids"),300,36,"规则编号");require(!ids.isEmpty(),422,"请选择规则");String action=text(b,"action");require(Arrays.asList("enable","disable","delete","copy").contains(action),422,"批量操作无效");for(String rid:ids){Map<String,Object> r=rules(c).stream().filter(x->rid.equals(x.get("id"))).findFirst().orElse(null);require(r!=null,404,"部分规则已不存在");if(action.equals("delete"))rules(c).remove(r);else if(action.equals("copy")){Map<String,Object> copy=new LinkedHashMap<>(r);copy.put("id",id());copy.put("title",str(r.get("title"))+"（副本）");copy.put("state","draft");copy.put("updatedAt",now());rules(c).add(copy);}else{r.put("state",action.equals("enable")?"enabled":"disabled");r.put("updatedAt",now());}}save(a,row,c);return view(a);}
    @Transactional public Map<String,Object> settings(EhrActor a,Map<String,Object> b){Map<String,Object> row=editing(a,b),c=draft(row);require(b.get("enabled") instanceof Boolean&&b.get("knowledge") instanceof List,422,"配置无效");c.put("enabled",b.get("enabled"));c.put("knowledge",b.get("knowledge"));save(a,row,c);return view(a);}
    @Transactional public Map<String,Object> importRules(EhrActor a,Map<String,Object> b){Map<String,Object> row=editing(a,b),c=draft(row);require(b.get("rules") instanceof List,422,"导入JSON须含rules数组");List<?> raw=(List<?>)b.get("rules");require(!raw.isEmpty()&&raw.size()<=100,422,"每次导入1至100条规则");List<Map<String,Object>> imported=new ArrayList<>();for(Object item:raw){require(item instanceof Map,422,"每条规则须为对象");Map<String,Object> input=new LinkedHashMap<>((Map<String,Object>)item);input.put("state","draft");if(!input.containsKey("match"))input.put("match","any");imported.add(normalize(input));}rules(c).addAll(imported);save(a,row,c);return view(a);}
    @Transactional public Map<String,Object> publish(EhrActor a,Map<String,Object> b){Map<String,Object> row=editing(a,b),c=draft(row);validate(c);for(Map<String,Object> rule:rules(c))if("enabled".equals(rule.get("state"))&&"ai".equals(rule.get("type"))){require(knowledge(c).stream().anyMatch(k->Boolean.TRUE.equals(k.get("enabled"))&&((List<?>)rule.get("knowledgeIds")).contains(k.get("id"))),422,"启用的AI规则至少需要一个启用的知识来源："+rule.get("title"));}int number=(int)db.count("SELECT COALESCE(MAX(release_number),0)+1 FROM a_service_reply_releases WHERE scope_code=? AND data_mode=?",a.scope,a.mode);String release=id();db.insert("a_service_reply_releases",map("release_id",release,"scope_code",a.scope,"data_mode",a.mode,"release_number",number,"config_json",ehr.encode(c),"actor_user",a.user,"created_at",now()));db.exec("UPDATE a_service_reply_configs SET active_release_id=? WHERE scope_code=? AND data_mode=?",release,a.scope,a.mode);return view(a);}
    public List<Map<String,Object>> releases(EhrActor a){staff(a);return db.all("SELECT release_id id,release_number number,actor_user actor,created_at time FROM a_service_reply_releases WHERE scope_code=? AND data_mode=? ORDER BY release_number DESC LIMIT 30",a.scope,a.mode);}
    @Transactional public Map<String,Object> rollback(EhrActor a,Map<String,Object> b){Map<String,Object> row=editing(a,b);String release=text(b,"releaseId");Map<String,Object> prior=db.one("SELECT config_json FROM a_service_reply_releases WHERE release_id=? AND scope_code=? AND data_mode=?",release,a.scope,a.mode);require(prior!=null,404,"发布版本不存在");Map<String,Object> c=draftRelease(prior);save(a,row,c);Map<String,Object> next=map("version",num(row.get("draft_version"))+1);return publish(a,next);}
    public Map<String,Object> statistics(EhrActor a){staff(a);String where=" FROM a_service_reply_events e JOIN a_service_conversations c ON c.conversation_id=e.conversation_id WHERE c.scope_code=? AND c.data_mode=?";Map<String,Object> m=db.one("SELECT COUNT(*) requests,COALESCE(SUM(e.outcome='replied'),0) replies,COALESCE(SUM(e.outcome='handoff'),0) handoffs,COALESCE(SUM(e.outcome='failed'),0) failures,COALESCE(SUM(e.outcome='queued' OR e.outcome='running'),0) processing,ROUND(100.0*SUM(e.outcome='replied')/NULLIF(SUM(e.outcome IN ('replied','handoff','failed')),0),1) hitRate"+where+" AND e.created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY)",a.scope,a.mode);m.put("trend",db.all("SELECT DATE_FORMAT(DATE_ADD(e.created_at,INTERVAL 8 HOUR),'%Y-%m-%d') day,COUNT(*) requests,SUM(e.outcome='replied') hits"+where+" AND e.created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY) GROUP BY day ORDER BY day",a.scope,a.mode));m.put("rules",db.all("SELECT e.rule_id id,COUNT(*) hits,SUM(e.outcome='replied') replies,SUM(e.outcome='handoff') handoffs,COUNT(d.satisfaction_score) ratings,ROUND(100.0*SUM(d.satisfaction_score>=4)/NULLIF(COUNT(d.satisfaction_score),0),1) satisfaction"+where.replace(" WHERE", " LEFT JOIN a_service_conversation_details d ON d.conversation_id=c.conversation_id WHERE")+" GROUP BY e.rule_id",a.scope,a.mode));m.put("suggestions",db.all("SELECT e.outcome,COUNT(*) count"+where+" AND e.created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY) AND e.outcome IN ('failed','handoff') GROUP BY e.outcome",a.scope,a.mode));return m;}
}
